import { Text } from "@react-email/components";
import type { ReactElement } from "react";
import { formatDate } from "@/lib/date";
import { humanizeRole } from "@/lib/format";
import type { IsoTimestamp } from "@/types/common";
import type { Role } from "@/types/member";
import { EmailButton } from "./_components/email-button";
import { EmailLayout } from "./_components/email-layout";

export type InviteEmailProps = {
  inviterName: string;
  orgName: string;
  role: Role;
  acceptUrl: string;
  expiresAt: IsoTimestamp;
};

const styles = {
  paragraph: { color: "#374151", fontSize: "15px", lineHeight: "24px" },
  muted: { color: "#6b7280", fontSize: "13px", lineHeight: "20px" },
};

export function InviteEmail(props: InviteEmailProps): ReactElement | null {
  const { inviterName, orgName, role, acceptUrl, expiresAt } = props;

  return (
    <EmailLayout
      preview={`${inviterName} invited you to ${orgName} on Taskflow`}
      heading={`Join ${orgName}`}
    >
      <Text style={styles.paragraph}>
        {inviterName} invited you to work in <strong>{orgName}</strong> as a{" "}
        <strong>{humanizeRole(role)}</strong>.
      </Text>
      <EmailButton href={acceptUrl} label="Accept invitation" />
      <Text style={styles.muted}>
        This invitation expires on {formatDate(expiresAt)}. If you were not
        expecting it, you can ignore this email.
      </Text>
    </EmailLayout>
  );
}

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const members = sqliteTable(
  "members",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    status: text("status", { enum: ["active", "invited", "suspended"] })
      .notNull()
      .default("active"),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at"),
    lastSeenAt: text("last_seen_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("members_org_user_idx").on(table.orgId, table.userId),
    index("members_org_role_idx").on(table.orgId, table.role),
  ],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: idColumn(),
    ...tenantColumns,
    email: text("email").notNull(),
    role: text("role", { enum: ["owner", "admin", "member", "viewer"] })
      .notNull()
      .default("member"),
    invitedBy: text("invited_by").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    acceptedAt: text("accepted_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("invitations_token_idx").on(table.tokenHash),
    index("invitations_org_email_idx").on(table.orgId, table.email),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;

